CREATE TRIGGER vane_raw_occurrence_reassign AFTER UPDATE OF group_id,site,token ON vane_raw_occurrences
 WHEN EXISTS(SELECT 1 FROM vane_raw_groups previous
 JOIN vane_raw_groups current ON current.group_id=NEW.group_id
 WHERE previous.group_id=OLD.group_id AND (previous.context=current.context AND previous.at_offset IS current.at_offset)) BEGIN
DELETE FROM vane_raw_groups WHERE group_id=OLD.group_id
 AND NOT EXISTS(SELECT 1 FROM vane_raw_occurrences WHERE group_id=OLD.group_id);
 END ;
